page.css:
:root {
  --paper: #eef1ec; --sheet: #fbfcfa; --sheet-2: #f1f4ef; --ink: #17201b; --muted: #56625b; --faint: #8e9a93; --rule: #d5ddd6;
  --brass: #a8700c; --brass-2: #c98f22; --brass-soft: #f6e6c2; --cow: #2f5d4a; --turf: #24734f; --turf-soft: #d9eee2; --loss: #b23a2c; --loss-soft: #f5dcd6;
  --room: #16352a; --room-2: #20493a; --room-ink: #eef3ec; --room-muted: #a9c0b4; --plate-ink: #f0c75e; --badge-ink: #ffffff; --wall: #e4eae3;
  --c0: #a8700c; --c1: #1f5f9e; --c2: #24734f; --c3: #8a3f8f; --c4: #b23a2c; --c5: #1f8a8a; --c6: #5a4fb0; --c7: #c2557a; --c8: #6b7a1f; --c9: #4a86c8; --c10: #8c5a2b; --c11: #4f5d68; --c12: #2c9a6a; --c13: #9c6b00; --c14: #6e3fa3;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --paper: #111814; --sheet: #18221d; --sheet-2: #1e2a24; --ink: #e9efea; --muted: #a2b0a8; --faint: #6c7a72; --rule: #2a3831;
  --brass: #e7b14a; --brass-2: #f0c770; --brass-soft: #3a2e17; --cow: #8fc4aa; --turf: #6fcf9f; --turf-soft: #1b3428; --loss: #f08b7c; --loss-soft: #3d2420;
  --room: #0c1f18; --room-2: #163428; --room-ink: #eef3ec; --room-muted: #93ad9f; --plate-ink: #f3cf73; --badge-ink: #111814; --wall: #141d18;
  --c0: #e7b14a; --c1: #7fb1ea; --c2: #6fcf9f; --c3: #d38ad8; --c4: #f08b7c; --c5: #5fcaca; --c6: #a59cf0; --c7: #ee95b2; --c8: #b8c860; --c9: #9cc6f4; --c10: #d9a473; --c11: #a7b4be; --c12: #7fe0b1; --c13: #f2c95c; --c14: #c39af0;
  color-scheme: dark } }
:root[data-theme="dark"] {
  --paper: #111814; --sheet: #18221d; --sheet-2: #1e2a24; --ink: #e9efea; --muted: #a2b0a8; --faint: #6c7a72; --rule: #2a3831;
  --brass: #e7b14a; --brass-2: #f0c770; --brass-soft: #3a2e17; --cow: #8fc4aa; --turf: #6fcf9f; --turf-soft: #1b3428; --loss: #f08b7c; --loss-soft: #3d2420;
  --room: #0c1f18; --room-2: #163428; --room-ink: #eef3ec; --room-muted: #93ad9f; --plate-ink: #f3cf73; --badge-ink: #111814; --wall: #141d18;
  --c0: #e7b14a; --c1: #7fb1ea; --c2: #6fcf9f; --c3: #d38ad8; --c4: #f08b7c; --c5: #5fcaca; --c6: #a59cf0; --c7: #ee95b2; --c8: #b8c860; --c9: #9cc6f4; --c10: #d9a473; --c11: #a7b4be; --c12: #7fe0b1; --c13: #f2c95c; --c14: #c39af0;
  color-scheme: dark }
/* No painting: the wordmark takes the whole masthead. */
.mast-top, .mast.compact .mast-top { grid-template-columns: minmax(0, 1fr); }
.brand h1 .cow { color: var(--ink); }
.brand h1 .ver { color: var(--brass); display: block; }
.mast.compact .brand h1 .ver { display: inline; }
.mast { border-bottom: 4px solid var(--brass); }
